def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    anchors = {}

    # A one-cell gap inside a horizontal run marks a vertical crossing.
    for r in range(h):
        for c in range(1, w - 1):
            if g[r][c] == 0 and g[r][c - 1] == g[r][c + 1] != 0:
                color = g[r][c - 1]
                g[r][c] = color
                anchors.setdefault(c, []).append((r, color))

    for c, marks in anchors.items():
        marks.sort()
        # Extend the uppermost crossing to the top edge.
        first_r, first_color = marks[0]
        for r in range(first_r):
            if g[r][c] == 0:
                g[r][c] = first_color

        # Between crossings, the lower crossing's color fills the interval.
        for (r1, _), (r2, lower_color) in zip(marks, marks[1:]):
            for r in range(r1 + 1, r2):
                if g[r][c] == 0:
                    g[r][c] = lower_color

        # If a vertical stem exists below the final crossing, extend its
        # color up to that crossing.
        last_r = marks[-1][0]
        below = [(r, g[r][c]) for r in range(last_r + 1, h) if g[r][c] != 0]
        if below:
            color = below[0][1]
            for r in range(last_r + 1, h):
                if g[r][c] == 0:
                    g[r][c] = color

    return g
